mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, pro.P_Name as pName, c1.C_Name as caContractorName, c2.C_Name as caSupervisorName, c3.C_Name as caApplicantName, c1.C_Abbreviation as caContractorAbbName, c2.C_Abbreviation as caSupervisorAbbName, c3.C_Abbreviation as caApplicantAbbName, sec.Sec_Name as secName, f.file_relation_id as fileRelationId, mn.* from Completion_Acceptance mn left join Con_Contract con on con.Con_Id = mn.Con_Id left join Pre_Project pro on pro.P_Id = mn.P_Id left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join SYS_Company c1 on mn.Ca_Contractor_Id = c1.C_Id left join SYS_Company c2 on mn.Ca_Supervisor_Id = c2.C_Id left join SYS_Company c3 on mn.Ca_Applicant = c3.C_Id left join Sys_File f on f.FileID = mn.Ca_Id where mn.P_Id = #{params.pId}
and mn.Ca_Type=#{params.caType}
and mn.Ca_State=7 order by mn.Ca_State_Time desc limit 1

select con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, c1.C_Name_History as caContractorNameHistory, c2.C_Name_History as caSupervisorNameHistory, c1.C_Name as caContractorName, c2.C_Name as caSupervisorName, c3.C_Name as caApplicantName, c1.C_Abbreviation as caContractorAbbName, c2.C_Abbreviation as caSupervisorAbbName, c3.C_Abbreviation as caApplicantAbbName, sec.Sec_Name as secName,
(select
from Completion_Acceptance_Section cas left join Sec_Info si on si.Sec_Id=cas.Sec_Id where cas.Ca_Id=mn.Ca_Id) as secGroupName, mn.* from Completion_Acceptance mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Ca_Contractor_Id=c1.C_Id left join SYS_Company c2 on mn.Ca_Supervisor_Id=c2.C_Id left join SYS_Company c3 on mn.Ca_Applicant = c3.C_Id
${params.authSql}
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ca_Create_Time DESC

select sum(mn.Ca_Con_Money) as caConMoneySum, sum(mn.Ca_Settlement_Money) as caSettlementMoneySum from Completion_Acceptance mn left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Ca_Contractor_Id=c1.C_Id left join SYS_Company c2 on mn.Ca_Supervisor_Id=c2.C_Id left join SYS_Company c3 on mn.Ca_Applicant = c3.C_Id
${params.authSql}
where 1=1
